<?php namespace BinerMail;
class OAuth{public function authorize(array $u,string $clientId,string $redirect,string $scope,string $state=''):string{$p=Database::pdo();$s=$p->prepare('SELECT * FROM bm_oauth_clients WHERE client_id=? AND user_id=?');$s->execute([$clientId,$u['id']]);$c=$s->fetch();$allowed=array_filter(array_map('trim',preg_split('/\R/',$c['redirect_uris']??'')));if(!$c||!in_array($redirect,$allowed,true))throw new \RuntimeException('Invalid OAuth client or redirect URI');$code=random_token(32);$s=$p->prepare('INSERT INTO bm_oauth_codes(code_hash,client_id,user_id,redirect_uri,scope,expires_at) VALUES(?,?,?,?,?,DATE_ADD(NOW(),INTERVAL 5 MINUTE))');$s->execute([token_hash($code),$clientId,$u['id'],$redirect,$scope]);return $redirect.(str_contains($redirect,'?')?'&':'?').'code='.rawurlencode($code).($state!==''?'&state='.rawurlencode($state):'');}public function token(array $i):array{$p=Database::pdo();$s=$p->prepare('SELECT * FROM bm_oauth_clients WHERE client_id=?');$s->execute([$i['client_id']??'']);$c=$s->fetch();if(!$c||!password_verify((string)($i['client_secret']??''),$c['client_secret_hash']))throw new \RuntimeException('Invalid client credentials');$s=$p->prepare('SELECT * FROM bm_oauth_codes WHERE code_hash=? AND client_id=? AND used_at IS NULL AND expires_at>NOW()');$s->execute([token_hash((string)($i['code']??'')),$c['client_id']]);$r=$s->fetch();if(!$r)throw new \RuntimeException('Invalid or expired authorization code');$p->prepare('UPDATE bm_oauth_codes SET used_at=NOW() WHERE id=?')->execute([$r['id']]);$access=random_token(32);$refresh=random_token(48);$p->prepare('INSERT INTO bm_oauth_tokens(token_hash,client_id,user_id,scope,expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR))')->execute([token_hash($access),$c['client_id'],$r['user_id'],$r['scope']]);$p->prepare('INSERT INTO bm_refresh_tokens(token_hash,client_id,user_id,scope,expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 30 DAY))')->execute([token_hash($refresh),$c['client_id'],$r['user_id'],$r['scope']]);return ['access_token'=>$access,'token_type'=>'Bearer','expires_in'=>3600,'refresh_token'=>$refresh,'scope'=>$r['scope']];}public function userFromBearer(string $token):?array{$s=Database::pdo()->prepare('SELECT u.* FROM bm_oauth_tokens t JOIN bm_users u ON u.id=t.user_id WHERE t.token_hash=? AND t.expires_at>NOW() AND u.active=1');$s->execute([token_hash($token)]);return $s->fetch()?:null;}}
